const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const invoiceId = String(payload.invoiceId || payload.invoice_id || 'INV-UNKNOWN').trim();
const invoiceNumber = String(payload.invoiceNumber || invoiceId).trim();
const dueDateStr = String(payload.dueDate || payload.due_date || new Date().toISOString());
const dueDate = new Date(dueDateStr);
const now = Date.now();
const msOverdue = Math.max(0, now - dueDate.getTime());
const daysOverdue = Math.max(1, Math.floor(msOverdue / (1000 * 86400)));

const amountDue = Number(payload.amountDue || payload.amount || 0);
const currency = String(payload.currency || 'INR').toUpperCase();
const clientName = String(payload.clientName || payload.name || 'Valued Client').trim();
const clientEmail = String(payload.clientEmail || payload.email || '').trim().toLowerCase();
const projectId = String(payload.projectId || payload.project_id || '').trim();

let stage = 'STAGE_1_FRIENDLY_REMINDER';
let urgency = 'COURTESY';
let actionSummary = 'Gentle reminder sent with invoice PDF attachment & instant payment link';
let suspensionWarning = false;
let sprintHoldTriggered = false;

if (daysOverdue > 14) {
  stage = 'STAGE_4_WORK_PAUSE_ESCALATION';
  urgency = 'CRITICAL';
  actionSummary = 'Engineering sprints placed on hold. Account flagged for legal and founder review.';
  suspensionWarning = true;
  sprintHoldTriggered = true;
} else if (daysOverdue > 7) {
  stage = 'STAGE_3_SUSPENSION_WARNING';
  urgency = 'HIGH';
  actionSummary = 'Formal notice that staging server access & sprint velocity will pause in 48 hours.';
  suspensionWarning = true;
} else if (daysOverdue > 3) {
  stage = 'STAGE_2_URGENT_NOTICE';
  urgency = 'ELEVATED';
  actionSummary = 'Second follow-up notice highlighting overdue terms and upcoming grace period expiration.';
}

const requiresFounderReview = daysOverdue >= 8;

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    escalation: {
      invoiceId,
      invoiceNumber,
      daysOverdue,
      stage,
      urgency,
      amountDue,
      currency,
      clientName,
      clientEmail,
      projectId,
      suspensionWarning,
      sprintHoldTriggered,
      requiresFounderReview,
      actionSummary,
      evaluatedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const esc = item.escalation;

const noticePacket = {
  subject: `[${esc.urgency}] Invoice ${esc.invoiceNumber} Overdue (${esc.daysOverdue} Days) — Logic Intelligence Technologies`,
  recipientEmail: esc.clientEmail,
  recipientName: esc.clientName,
  amountDueFormatted: `${esc.currency} ${esc.amountDue.toLocaleString('en-IN')}`,
  stage: esc.stage,
  sprintStatus: esc.sprintHoldTriggered ? 'PAUSED' : 'ACTIVE_PENDING_PAYMENT',
  paymentPortalPath: `/portal/billing/pay?invoice=${esc.invoiceNumber}`,
  escalationRecipient: esc.requiresFounderReview ? 'Vikash Saravanan (Lead System Engineer)' : 'Operations Desk'
};

return [{
  json: {
    eventId: item.eventId,
    status: 'overdue_escalation_processed',
    detail: {
      escalation: esc,
      notice: noticePacket,
      dispatchedAt: new Date().toISOString()
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
